const fs = require("fs");
const regions = ["north", "south", "east", "west"];
const expected = {
  north: { count: 10, units: 90, weighted: 167 },
  south: { count: 10, units: 94, weighted: 171 },
  east:  { count: 10, units: 98, weighted: 209 },
  west:  { count: 10, units: 85, weighted: 145 }
};
const out = {};
let failures = 0;
for (const r of regions) {
  const rows = JSON.parse(fs.readFileSync(r + ".json", "utf8"));
  if (!Array.isArray(rows)) throw new Error(r + ": not a top-level array");
  let count = 0, units = 0, weighted = 0;
  for (const row of rows) {
    if (!Number.isInteger(row.units) || !Number.isInteger(row.weight)) {
      throw new Error(r + ": non-integer units/weight in id " + row.id);
    }
    count += 1;
    units += row.units;
    weighted += row.units * row.weight;
  }
  const exp = expected[r];
  const ok = count === exp.count && units === exp.units && weighted === exp.weighted;
  if (!ok) failures++;
  out[r] = { count, units, weighted, inspector: exp, match: ok };
  console.log(
    (ok ? "MATCH " : "MISMATCH ") + r.padEnd(5) +
    " recomputed{count=" + count + ", units=" + units + ", weighted=" + weighted + "}" +
    " inspector{count=" + exp.count + ", units=" + exp.units + ", weighted=" + exp.weighted + "}"
  );
}
const grandUnits = regions.reduce((s, r) => s + out[r].units, 0);
const grandWeighted = regions.reduce((s, r) => s + out[r].weighted, 0);
console.log("grand_units=" + grandUnits + " grand_weighted=" + grandWeighted);
fs.writeFileSync("verified.json", JSON.stringify({ regions: out, grand_units: grandUnits, grand_weighted: grandWeighted }, null, 2));
if (failures) { console.error("FAILED: " + failures + " region(s) disagree with inspector reports"); process.exit(1); }
console.log("ALL 4 INSPECTOR REPORTS VERIFIED");
'

