arguments.content:
'use strict';
const fs = require('fs');
const path = require('path');

const dir = __dirname;
const REGIONS = ['north', 'south', 'east', 'west'];
const fails = [];

function check(cond, msg) {
  if (!cond) fails.push(msg);
}

// --- recompute each region independently from its own source file ---
const recomputed = {};
for (const r of REGIONS) {
  const file = path.join(dir, r + '.json');
  check(fs.existsSync(file), `missing source file ${r}.json`);
  const raw = fs.readFileSync(file, 'utf8');
  const data = JSON.parse(raw);
  check(Array.isArray(data), `${r}.json top level is not an array`);

  let units = 0;
  let weighted = 0;
  const ids = new Set();
  for (const rec of data) {
    check(rec !== null && typeof rec === 'object', `${r}.json has a non-object record`);
    const { id, units: u, weight: w } = rec;
    check(Number.isInteger(u), `${r}.json record id=${id} has non-integer units`);
    check(Number.isInteger(w), `${r}.json record id=${id} has non-integer weight`);
    check(!ids.has(id), `${r}.json has duplicate id ${id}`);
    ids.add(id);
    units += u;
    weighted += u * w;
  }
  recomputed[r] = { count: data.length, units, weighted };
}

// --- read and validate answer.json ---
const answerPath = path.join(dir, 'answer.json');
check(fs.existsSync(answerPath), 'missing answer.json');
const answer = JSON.parse(fs.readFileSync(answerPath, 'utf8'));

check(answer !== null && typeof answer === 'object' && !Array.isArray(answer),
  'answer.json top level is not an object');
check(answer.regions !== null && typeof answer.regions === 'object' && !Array.isArray(answer.regions),
  'answer.json regions is not an object');
check(Number.isInteger(answer.grand_units), 'grand_units is not an integer');
check(Number.isInteger(answer.grand_weighted), 'grand_weighted is not an integer');

// exact key set: no missing region, no extra region
const answerKeys = Object.keys(answer).sort();
check(JSON.stringify(answerKeys) === JSON.stringify(['grand_units', 'grand_weighted', 'regions']),
  `answer.json top-level keys are ${JSON.stringify(answerKeys)}`);
const regionKeys = Object.keys(answer.regions || {}).sort();
check(JSON.stringify(regionKeys) === JSON.stringify([...REGIONS].sort()),
  `region keys are ${JSON.stringify(regionKeys)}, expected ${JSON.stringify([...REGIONS].sort())}`);

// --- per-region schema + value comparison against recomputation ---
for (const r of REGIONS) {
  const got = answer.regions[r];
  const exp = recomputed[r];
  if (got === undefined) { fails.push(`answer.json missing region ${r}`); continue; }
  const keys = Object.keys(got).sort();
  check(JSON.stringify(keys) === JSON.stringify(['count', 'units', 'weighted']),
    `region ${r} keys are ${JSON.stringify(keys)}`);
  for (const f of ['count', 'units', 'weighted']) {
    check(Number.isInteger(got[f]), `region ${r}.${f} is not an integer`);
    check(got[f] === exp[f], `region ${r}.${f} = ${got[f]}, recomputed ${exp[f]}`);
  }
}

// --- grand totals ---
const grandUnits = REGIONS.reduce((s, r) => s + recomputed[r].units, 0);
const grandWeighted = REGIONS.reduce((s, r) => s + recomputed[r].weighted, 0);
check(answer.grand_units === grandUnits, `grand_units = ${answer.grand_units}, recomputed ${grandUnits}`);
check(answer.grand_weighted === grandWeighted, `grand_weighted = ${answer.grand_weighted}, recomputed ${grandWeighted}`);

// grand totals must also equal the sum of the answer's own region entries
const ansUnits = REGIONS.reduce((s, r) => s + (answer.regions[r] ? answer.regions[r].units : 0), 0);
const ansWeighted = REGIONS.reduce((s, r) => s + (answer.regions[r] ? answer.regions[r].weighted : 0), 0);
check(answer.grand_units === ansUnits, `grand_units inconsistent with summed region units ${ansUnits}`);
check(answer.grand_weighted === ansWeighted, `grand_weighted inconsistent with summed region weighted ${ansWeighted}`);

// --- source completeness: every source file on disk is represented, and vice versa ---
const sourceFiles = fs.readdirSync(dir).filter((f) => /^(north|south|east|west)\.json$/.test(f)).map((f) => f.replace(/\.json$/, '')).sort();
check(JSON.stringify(sourceFiles) === JSON.stringify([...REGIONS].sort()),
  `source files on disk are ${JSON.stringify(sourceFiles)}`);
const recordsTotal = REGIONS.reduce((s, r) => s + recomputed[r].count, 0);
check(recordsTotal === REGIONS.reduce((s, r) => s + answer.regions[r].count, 0),
  'summed region counts disagree with recomputed record counts');

// --- report ---
for (const r of REGIONS) {
  const e = recomputed[r];
  const a = answer.regions[r] || {};
  console.log(`${r.padEnd(5)} source: count=${e.count} units=${e.units} weighted=${e.weighted} | answer: count=${a.count} units=${a.units} weighted=${a.weighted}`);
}
console.log(`sources checked: ${sourceFiles.join(', ')} | records total: ${recordsTotal}`);
console.log(`grand_units=${answer.grand_units} (recomputed ${grandUnits}) grand_weighted=${answer.grand_weighted} (recomputed ${grandWeighted})`);

if (fails.length) {
  console.error('FAILED:\n - ' + fails.join('\n - '));
  process.exit(1);
}
console.log('ALL ASSERTIONS PASSED: answer.json schema, region values, grand totals, source completeness');
